 class Task implements Callable<Object> {
    int n,m;
    int[] r;
    int[][] q;



    public Task(int n, int p, int[] r, int[][] q) {
        super();
        this.n = n;
        this.m = p;
        this.r = r;
        this.q = q;
    }



    @Override
    public Object call() throws Exception {
        for(int i=0;i<n;i++) {
            Arrays.sort(q[i]);
        }
        int[][] ql = new int[n][m];
        int[][] qr = new int[n][m];
        for(int i=0;i<n;i++) {
            for(int j=0;j<m;j++) {
                ql[i][j] = divCeil(10 * q[i][j], 11 * r[i]);
                qr[i][j] = (10 * q[i][j]) / (9 * r[i]);
            }
        }
        int ans = 0;
        int[] idx = new int[n];
        for(int k=1;k<=1111112;k++) {
            while(true) {
                for(int i=0;i<n;i++) {
                    while (idx[i] < m && qr[i][idx[i]] < k) {
                        idx[i]++;
                    }
                }
                boolean flag = true;
                for(int i=0;i<n;i++) {
                    if (idx[i] < m && ql[i][idx[i]] <= k && k <= qr[i][idx[i]]) {

                    }else{
                        flag = false;
                        break;
                    }
                }
                if (flag) {
                    for(int i=0;i<n;i++) {
                        idx[i]++;
                    }
                    ans++;
                }else{
                    break;
                }
            }
        }
        return ans;
    }

    public static int divCeil(int a, int b) {
        return (a + b - 1) / b;
    }

 }

