package exo1;










 public class Exo extends Base {

    public static void main(String[] argv) {






        configSmall(0, false);





        try {
            int testCaseCount = input().nextInt();
            for (int i = 1; i <= testCaseCount; ++i) {
                info("CASE #" + i + " ###################################################");





                output().println("Case #" + i + ": " + solveTestCase());



            }
        }
        catch (Exception e) {
            e.printStackTrace(System.err);
        }
        finally {
            done();
        }
    }





    private static double solveTestCase() {

        int D = input().nextInt();
        int N = input().nextInt();

        double Tf = 0;
        for (int i = 0; i < N; ++i) {
            double ki = input().nextInt();
            double si = input().nextInt();

            double currentT = (D - ki) / si;
            Tf = Math.max(Tf, currentT);
        }

        return D / Tf;
    }

 }









