     static int bruteforce(String line, int k) {
         HashMap<String, Integer> map = new HashMap();
         LinkedList<String> q = new LinkedList();
         q.add(line);
         map.put(line, 0);
         while (!q.isEmpty()) {
             String v = q.poll();
             int cost = map.get(v);
             if (check(v)) {
                 return cost;
             }
             for (int i = 0; i < v.length(); i++) {
                 if (i + k <= v.length()) {
                     String a = v.substring(0, i);
                     String c = v.substring(i + k);
                     String b = rev(v.substring(i, i + k));
                     String re = a + b + c;
                     if (!map.containsKey(re)) {
                         map.put(re, cost + 1);
                         q.add(re);
                     }
                 }
             }
         }
         return -1;
     }

     static boolean check(String v) {
         for (int i = 0; i < v.length(); i++) {
             if (v.charAt(i) != '+') {
                 return false;
             }
         }
         return true;
     }

     static String rev(String tmp) {
         StringBuilder builder = new StringBuilder();
         for (int i = 0; i < tmp.length(); i++) {
             if (tmp.charAt(i) == '+') {
                 builder.append('-');
             } else {
                 builder.append('+');
             }
         }
         return builder.toString();
     }

     static int cal(int index, boolean[] flip, int k, String line) {
         if (index == line.length()) {
             return 0;
         }
         boolean flipped = flip[index];

         boolean happy = (line.charAt(index) == '+' && !flipped) || (line.charAt(index) == '-' && flipped);
         int result = -1;
         if (happy) {
             result = cal(index + 1, flip, k, line);
         } else if (index + k <= line.length()) {
             int st = index;
             int ed = index + k - 1;
             for (int i = index; i < index + k; i++) {
                 flip[i] = !flip[i];
             }

             int v = cal(index + 1, flip, k, line);
             if (v != -1) {
                 result = 1 + v;
             }
         }
         return result;

     }

     public static int[] KMP(String val) {
         int i = 0;
         int j = -1;
         int[] result = new int[val.length() + 1];
         result[0] = -1;
         while (i < val.length()) {
             while (j >= 0 && val.charAt(j) != val.charAt(i)) {
                 j = result[j];
             }
             j++;
             i++;
             result[i] = j;
         }
         return result;

     }

