    public boolean solve(int X, int rows, int columns) {

        if (X > rows && X > columns) {
            return true;
        }


        if (rows * columns % X != 0) {
            return true;
        }

        if ((rows+1) * 2 - 1 <= X || (columns+1) * 2 - 1 <= X) {
            return true;
        }






        if (X >= 7) {
            return true;
        }
        if(X>=4&&rows+columns-2<=X) {
            return true;
        }
        return false;
    }

