                 if (i + N > pat.length()) {
                     impos = true;
                     break;
                 }
                 for (int j = i; j < i + N; j++) {
                     p[j] = !p[j];
                 }
                 moves++;
             }
         }
         if (impos) {
             return "IMPOSSIBLE";
         }
         return "" + moves;
     }

