         for (int T = cin.nextInt(); T > 0; T--) {
             _case++;

             D = cin.nextInt();
             N = cin.nextInt();
             S = new double[N];
             K = new double[N];
             L = new double[N];

             for (int i = 0; i < N; i++) {
                 K[i] = cin.nextDouble();
                 S[i] = cin.nextDouble();
                 L[i] = (D - K[i]) / S[i];
             }

             double max = 0;
             for (double s : L)
                 max = Math.max(max, s);

             double ans = D / max;
             cout.printf("Case #%d: %.10f%n", _case, ans);
         }

         cin.close();
         cout.close();
     }
 }
