public class B {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    class State implements Comparable<State> {
        int idx;
        long now;

        State(int idx, long now) {
            this.idx = idx;
            this.now = now;
        }

        public int compareTo(State s) {
            if (s.now == now) return idx - s.idx;
            return Long.signum(now - s.now);
        }

        public String toString() {
            return getClass().getName() + " : " + idx + " " + now;
        }
    }

    long gcd(long x, long y) {
        if (x == 0 || y == 0) return x + y;
        return gcd(y, x % y);
    }

    long lcm(long x, long y) {
        return x * (y / gcd(x, y));
    }

    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            int res = 0;
            int B = in.nextInt(), N = in.nextInt() - 1;
            int[] m = in.nextIntArray(B);

            PriorityQueue<State> pq = new PriorityQueue<State>();
            for (int i = 0; i < B; i++) {
                pq.add(new State(i, 0));
            }

            long last = m[0];
            for (int i = 1; i < B; i++) {
                last = lcm(last, m[i]);
            }
            int loop = 0;
            while (!pq.isEmpty()) {
                State next = pq.poll();
                if (next.now == last) continue;
                loop++; 
                pq.add(new State(next.idx, next.now + m[next.idx]));
            }


            N %= loop;
            for (int i = 0; i < B; i++) {
                pq.add(new State(i, 0));
            }
            while (!pq.isEmpty()) {
                State next = pq.poll();

                if (N == 0) {
                    res = next.idx + 1;
                    break;
                }
                N--;
                pq.add(new State(next.idx, next.now + m[next.idx]));
            }

            out.println("Case #" + caseN + ": " + res);
        }
        out.close();
    }

    public static void main(String[] args) {
        new B().run();
    }

    public void mapDebug(int[][] a) {
        System.out.println("--------map display---------");

        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[i].length; j++) {
                System.out.printf("%3d ", a[i][j]);
            }
            System.out.println();
        }

        System.out.println("----------------------------");
        System.out.println();
    }

    public void debug(Object... obj) {
        System.out.println(Arrays.deepToString(obj));
    }

    class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;


        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
