                 String s = in.next();
                 boolean allOne = true;
                 for (int j = 0; j < s.length(); j++) {
                     allOne &= s.charAt(j) == '1';
                 }
                 ok &= !allOne;
             }
             String bad = in.next();
             out.printf("Case #%d: ", testNumber);
             if (!ok) out.println("IMPOSSIBLE");
             else {
                 String y = "";
                 for (int i = 0; i < l; i++) y += "0?";
                 String z = "";
                 for (int i = 0; i < l - 1; i++) z += "1";
                 z += "0";
                 out.printf("%s %s\n", y, z);
             }
         }

     }
 }

