    }

    int intLine(){
        return Integer.parseInt(scan.nextLine());
    }


    HashMap<Long,Integer>H=new HashMap<>();
    int doit(int p, int h, int v){
        long K = p +(1L<<10)*h +(1L<<20)*v;
        if(H.containsKey(K))return H.get(K);
        if(p==0) {
            if(v==((1<<2*C)-1)){
                return 0;
            }
        }
        int res = Integer.MAX_VALUE;
        int e1 = E[2*p];
        int l1=L[2*p];
        int d1=D[2*p];
        int t1=2*p;
        if((v&(1<<(t1)))==0) {
            int r =0;
            if(l1>=h)r=l1-h;
            else r = l1+24-h;
            r+=d1;
            int rr = doit(e1,(l1+d1)%24,v|(1<<t1) );
            if(rr!=Integer.MAX_VALUE){
                r+=rr;
                res = min(res,r);
            }
        }
        e1 = E[1+2*p];
        l1=L[1+2*p];
        d1=D[1+2*p];
        t1 = 2*p+1;
        if((v&(1<<t1))==0) {
            int r =0;
            if(l1>=h)r=l1-h;
            else r = l1+24-h;
            r+=d1;
            int rr = doit(e1,(l1+d1)%24,v|(1<<t1) );
            if(rr!=Integer.MAX_VALUE){
                r+=rr;
                res = min(res,r);
            }
        }
        H.put(K, res);
        return res;
    }

    public String solve() {
        C=scan.nextInt();
        E = new int[2*C];
        L = new int[2*C];
        D = new int[2*C];
        for(int i=0;i<2*C;i++){
            E[i]=scan.nextInt()-1;
            L[i]=scan.nextInt();
            D[i]=scan.nextInt();
        }
        int res = doit(0,0,0);
        return ""+res;
    }


