 class TaskB {
     public void solve(int testNumber, InputReader in, PrintWriter out) {
         out.print("Case #"+testNumber+": ");
         int B = in.nextInt();
         long N = in.nextLong();
         long[] m = new long[B];
         long hi = 1000000;
         for (int i = 0; i < B; i++) {
             m[i] = in.nextInt();
             hi = Math.min(hi, m[i]);
         }
         if (N <= B) {
             out.println(N);
             return;
         }
         hi *= N;
         long lo = 0;
         while (hi - lo > 1) {
             long mid = (hi+lo)/2L;
             long c = count(mid, m);
             if (c >= N) {
                 hi = mid;
             } else {
                 lo = mid;
             }
         }
         long trapdoor = hi;
         if (count(hi, m) >= N) {
             trapdoor = lo;
         }
         long already = count(trapdoor,m);
         for (int i = 0; i < B; i++) {
             if ((trapdoor+1) % m[i] == 0) {
                 already++;
                 if (already == N) {
                     out.println(i+1);
                     break;
                 }
             }
         }
     }

     long count(long time, long[] m) {
         long res = 0;
         for (int i = 0; i < m.length; i++) {
             res += time/m[i] + 1;
         }
         return res;
     }
 }

