    public void read() 
    {
        n = ni();
        K = ni();
        s = na(n-K+1);
    }

    public void process() 
    {
        int[] down = new int[K];
        int[] up = new int[K];
        int[] cur = new int[K];
        for(int i = 1;i < n-K+1;i++){
            int id = (i+K-1)%K;
            cur[id] += -s[i-1] + s[i];
            if(cur[id] < down[id]){
                down[id] = cur[id];
            }
            if(cur[id] > up[id]){
                up[id] = cur[id];
            }
        }

        int maxd = 0;
        for(int i = 0;i < K;i++){
            maxd = Math.max(maxd, up[i]-down[i]);
        }
        long space = 0;
        for(int i = 0;i < K;i++){
            space += maxd - (up[i]-down[i]);
        }

        long base = -1000000000;
        long tot = 0;
        for(int i = 0;i < K;i++){
            tot += base + (-down[i]);
        }
        long delta = (s[0]-tot) % K;
        if(delta <= space){
            out.println(maxd);
        }else{
            out.println(maxd+1);
        }
    }

