         int s1 = 0;
         int max = 0;
         for(int i=1;i<a.length;i++) {
             if(a[i]-a[i-1] < 0) {
                 s1 += a[i-1]-a[i];
                 max = Math.max(max, a[i-1]-a[i]);
             }
         }
         int s2 = 0;
         for(int i=0;i<a.length-1;i++) {
             if(a[i] >= max) {
                 s2 += max;
             } else {
                 s2 += a[i];
             }
         }
         return s1+" "+s2;
     }

