public class Main {

   public static void main(String args[]) {
     (new Main()).solve();
   }

   void solve() {

     Scanner cin = new Scanner(System.in);

     int T = cin.nextInt();
     for(int C=1; C<=T; ++C) {

        int row = cin.nextInt();
        int col = cin.nextInt();
        String array[] = new String[row];
        for(int i=0; i<row; ++i ) {
            array[i] = cin.next();
        }

        String ans[] = solve(array, row, col);

       System.out.println("Case #" + C + ":");
       for(int i =0; i<row; ++i) {
          System.out.println(ans[i]);
       }

     }

   }

   private static final int inf = 99999;

   String[] solve(String input[], int row, int col) {
      int minX[] = new int[26];
      int minY[] = new int[26];
      int maxX[] = new int[26];
      int maxY[] = new int[26];
      for(int i=0; i<26; ++i) {
          minX[i] = minY[i] = inf;
          maxX[i] = maxY[i] = -1; 
      }
      for(int i=0; i<row; ++i) {
          for(int j=0; j<col; ++j) {
              if( input[i].charAt(j) == '?' ) { continue; }
              int index = input[i].charAt(j) - 'A';
              minY[index] = Math.min(minY[index], i);
              minX[index] = Math.min(minX[index], j);
              maxY[index] = Math.max(maxY[index], i);
              maxX[index] = Math.max(maxX[index], j);
          }
      }
      for(int i=0; i<row; ++i) {
          for(int j=0; j<col; ++j) {
              boolean done = false;
              for(int k=0; k<26; ++k) {
                  if( minY[k] <= i && i <= maxY[k] && minX[k] <= j && j <= maxX[k] ) {
                      done = true;
                  }
              }
              if( done ) { continue; }

              for(int k=0; k<26; ++k) {
                  if( minY[k] > maxY[k] || minX[k] > maxX[k] ) { continue; }
                  int minYt = Math.min(minY[k], i);
                  int minXt = Math.min(minX[k], j);
                  int maxYt = Math.max(maxY[k], i);
                  int maxXt = Math.max(maxX[k], j);
                  boolean assign = true;
                  for(int l=0; l<26; ++l) {
                      if( k == l ) { continue; }
                      if( conflict(new int[] { minYt, minXt, maxYt, maxXt }, new int[] { minY[l], minX[l], maxY[l], maxX[l] }) ){
                          assign = false;
                          break;
                      }
                  }
                  if( assign ) {
                      minY[k] = minYt;
                      minX[k] = minXt;
                      maxY[k] = maxYt;
                      maxX[k] = maxXt;
