        @Override
        public void run() {
            Set<Long> jams = new TreeSet<>();
            List<List<BigInteger>> fs = new ArrayList<>();
            List<Long> vs = new ArrayList<>();
            for(; jams.size() != J; ) {
                long v = random.nextLong() & ((1L << N) - 1);
                v |= (1L << (N - 1)) | 1;
                List<BigInteger> f = jamCoinFactor(v);
                if(f != null && jams.add(v)) {
                    fs.add(f);
                    vs.add(v);

                }
            }
            out.println();
            for(int i = 0; i < J; i++) {
