        List<BigInteger> jamCoinFactor(long v) {
            for(int i = 2; i <= 10; i++) {
                final BigInteger x = toBigInteger(v, i);
                if(x.isProbablePrime(16)) {
                    return null;
                }
            }

            List<BigInteger> ps = new ArrayList<>();
            for(int i = 2; i <= 10; i++) {
                final BigInteger x = toBigInteger(v, i);

                long limit = (1 << 14) * (1 << 14);
                if(x.compareTo(BigInteger.valueOf(limit)) < 0) {
                    limit = x.longValue();
                }
                boolean ok = false;
                for(long j = 2; j*j <= limit; j++) {
                    BigInteger bj = BigInteger.valueOf(j);
                    if(x.mod(bj).equals(BigInteger.ZERO)) {
                        ok = true;
                        ps.add(bj);
                        break;
                    }
                }
                if(!ok) return null;
            }
            return ps;
        }

        BigInteger toBigInteger(long b2, long base) {
            BigInteger res = BigInteger.ZERO;
            BigInteger bv = BigInteger.ONE;
            while(b2 != 0) {
                res = res.add(BigInteger.valueOf(b2 & 1).multiply(bv));
                b2 >>>= 1;
                bv = bv.multiply(BigInteger.valueOf(base));
            }
            return res;
        }



