    class Config {
        public static final boolean DISP_PROGRESS = true;
        public static final boolean DISP_ELASPED_TIME = true;
        public static final boolean STDIO = false;

        public static final String BASE_DIR = "data\\R2\\B";
        public static final String IN_FILE = "B-small-attempt6.in";
        public static final String OUT_FILE = IN_FILE + "_out.txt";
        public static final int MAX_THREAD = 3;
    }



    static
    class ParallelSolver implements Runnable {
        private static final int mod = (int)1e9+7;

        int n;
        double v, x;
        double[] r;
        double[] c;
        public void readInput(final IOFast io) throws IOException {
            n = io.nextInt();
            v = io.nextDouble();
            x = io.nextDouble();
            r = new double[n];
            c = new double[n];
            for(int i = 0; i < n; i++) {
                r[i] = io.nextDouble();
                c[i] = io.nextDouble();
            }
        }

        static final double eps = 1e-9;

        @Override
        public void run() {
            if(n == 1) {
                if(x < c[0] - eps || x > c[0] + eps) {
                    out.println("IMPOSSIBLE");
                    return;
                }
                out.printf("%.10f\n", v / r[0]);
            }
            else if(n == 2) {
                double[] f = func(r[0], r[1], v, r[0]*c[0]-r[0]*x, r[1]*c[1]-r[1]*x, 0);
                if(x < Math.min(c[0], c[1]) - eps || x > Math.max(c[0], c[1]) + eps) {
                    out.println("IMPOSSIBLE");
                    return;
                }

                if(f == null) {
                    if(x < c[0] - eps || x > c[0] + eps) {
                        out.println("IMPOSSIBLE");
                        return;
                    }
                    out.printf("%.10f\n", v / (r[0] + r[1]));
                }
                else {
                    out.printf("%.10f\n", f[1]);
                }


            }
            else {
                out.println("BAD");
            }
        }

        double f(double a) {
            double v0 = r[0] * a;
            double v1 = r[1] * (1-a);
            return (v0*c[0]+v1*c[1])/(v0+v1);
        }

        double[] func(double a1, double b1, double c1, double a2, double b2, double c2) {
            double d = a1*b2-a2*b1;

            if(Math.abs(d)*100000 < eps) return null;

            double t1 = (b2*c1-b1*c2)/d;
            double t2 = (-a2*c1+a1*c2)/d;
            return new double[]{Math.min(t1, t2), Math.max(t1, t2)};

        }

        static void swap(int[] x, int i, int j) {
            int t = x[i];
            x[i] = x[j];
            x[j] = t;
        }

        static void swap(double[] x, int i, int j) {
            double t = x[i];
            x[i] = x[j];
            x[j] = t;
        }



        final Random random = new Random(System.currentTimeMillis());
