 import static java.util.Arrays.*;

 public class A {

    static
    class Config {
        public static final boolean DISP_PROGRESS = true;
        public static final boolean DISP_ELASPED_TIME = true;
        public static final boolean STDIO = false;

        public static final String BASE_DIR = "data\\r2" ;
        public static final String IN_FILE = "A-small-attempt1.in";
        public static final String OUT_FILE = IN_FILE + "_out.txt";
        public static final int MAX_THREAD = 1;
    }



    static
    class ParallelSolver implements Runnable {
        private static final int mod = (int)1e9+7;

        int n, p;
        int[] cnt;
        public void readInput(final IOFast io) throws IOException {
            n = io.nextInt();
            p = io.nextInt();


            cnt = new int[p];
            for (int g : io.nextIntArray(n)) {
                cnt[g%p]++;
            }

        }

        @Override
        public void run() {
            int ans = 0;
            ans += cnt[0];
            cnt[0] = 0;
            mp.clear();
            out.println(ans + dfs(0));
        }

        TreeMap<Integer, Integer> mp = new TreeMap<>();
        int dfs(int cur) {
            int key = 0;
            for (int i = 1; i < p; i++) key = key * 101 + cnt[i];
            if (mp.containsKey(key)) return mp.get(key);
            int res = 0;
            for (int i = 1; i < p; i++) if (cnt[i] > 0) {
                cnt[i]--;
                res = Math.max(res, dfs(cur + i) + (cur%p==0?1:0));
                cnt[i]++;
            }
            mp.put(key, res);
            return res;
        }



        void printList(int[] res) {
            for(int i = 0; i < res.length; i++) {
                out.print(res[i] + (i==res.length-1?"\n":" "));
            }
        }
        void printList(List<Integer> res) {
            for(int i = 0; i < res.size(); i++) {
                out.print(res.get(i) + (i==res.size()-1?"\n":" "));
            }
        }


        final Random random = new Random(System.currentTimeMillis());
        final StringWriter sw = new StringWriter();
        final PrintWriter out = new PrintWriter(sw);

        @Override
        public String toString() {
            out.flush();
            return sw.toString();
        }

