    static final int DIJ[] = {0, 1, 0, -1, 0};

    static class HK {
        static int n;
        static boolean edges[][];
        static int matchingL[], matchingR[];
        static int hkDist[], hkQueue[];

        static void init() {
            edges = new boolean[n][n];
            matchingL = new int[n];
            matchingR = new int[n];
            hkDist = new int[n];
            hkQueue = new int[2 * n];
        }

        static int hopcroftKarp() {
            fill(matchingL, -1);
            fill(matchingR, -1);
            int size = 0;
            while (true) {
                fill(hkDist, -1);
                int queueHead = 0, queueTail = 0;
                for (int i = 0; i < n; i++) {
                    if (matchingL[i] < 0) {
                        hkQueue[queueTail++] = i;
                        hkQueue[queueTail++] = 0;
                    }
                }
                int resDist = -1;
                while (queueHead < queueTail) {
                    int cur = hkQueue[queueHead++];
                    int cdist = hkQueue[queueHead++];
                    if ((cdist + Integer.MIN_VALUE) > (resDist + Integer.MIN_VALUE)) {
                        break;
                    }
                    for (int next = 0; next < n; next++) {
                        if (!edges[cur][next] || hkDist[next] != -1) {
                            continue;
                        }
                        hkDist[next] = cdist;
                        int next2 = matchingR[next];
                        if (next2 < 0) {
                            resDist = cdist;
                        } else {
                            hkQueue[queueTail++] = next2;
                            hkQueue[queueTail++] = cdist + 1;
                        }
                    }
                }
                if (resDist == -1) {
                    return size;
                }
                for (int i = 0; i < n; i++) {
                    if (matchingL[i] < 0 && hopcroftKarpDfs(i, 0)) {
                        ++size;
                    }
                }
            }
        }

        static boolean hopcroftKarpDfs(int cur, int cdist) {
            for (int next = 0; next < n; next++) {
                if (!edges[cur][next] || hkDist[next] != cdist) {
                    continue;
                }
                hkDist[next] = -1;
                int next2 = matchingR[next];
                if (next2 < 0 || hopcroftKarpDfs(next2, cdist + 1)) {
                    matchingR[next] = cur;
                    matchingL[cur] = next;
                    return true;
                }
            }
            return false;
        }
    }

    static class IntList {

        int data[] = new int[3];
        int size = 0;

        boolean isEmpty() {
            return size == 0;
        }

        int size() {
            return size;
        }

        int get(int index) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            return data[index];
        }

        void clear() {
            size = 0;
        }

        void set(int index, int value) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            data[index] = value;
        }

        void expand() {
            if (size >= data.length) {
                data = copyOf(data, (data.length << 1) + 1);
            }
        }

        void insert(int index, int value) {
            if (index < 0 || index > size) {
                throw new IndexOutOfBoundsException();
            }
            expand();
            arraycopy(data, index, data, index + 1, size++ - index);
            data[index] = value;
        }

        int remove(int index) {
            if (index < 0 || index >= size) {
                throw new IndexOutOfBoundsException();
            }
            int value = data[index];
            arraycopy(data, index + 1, data, index, --size - index);
            return value;
        }

        void push(int value) {
            expand();
            data[size++] = value;
        }

        int pop() {
            if (size == 0) {
                throw new NoSuchElementException();
            }
            return data[--size];
        }

        void unshift(int value) {
            expand();
            arraycopy(data, 0, data, 1, size++);
            data[0] = value;
        }

        int shift() {
            if (size == 0) {
                throw new NoSuchElementException();
            }
            int value = data[0];
            arraycopy(data, 1, data, 0, --size);
            return value;
        }
    }

    static void solve() throws Exception {
        int m = nextInt();
        int n = nextInt();
        int moves = nextInt();
        boolean map[][] = new boolean[n][m];
        int nSoldiers = 0;
        int soldierI[] = new int[n * m];
        int soldierJ[] = new int[n * m];
        nTurrets = 0;
        int turretI[] = new int[n * m];
        int turretJ[] = new int[n * m];
        for (int i = 0; i < n; i++) {
            String l = next();
            for (int j = 0; j < m; j++) {
                switch (l.charAt(j)) {
                case '#':
                    break;
                case '.':
                    map[i][j] = true;
                    break;
                case 'S':
                    map[i][j] = true;
                    soldierI[nSoldiers] = i;
                    soldierJ[nSoldiers] = j;
                    ++nSoldiers;
                    break;
                case 'T':
                    map[i][j] = true;
                    turretI[nTurrets] = i;
                    turretJ[nTurrets] = j;
                    ++nTurrets;
                    break;
                default:
                    throw new AssertionError();
                }
            }
        }
        int reach[][][] = new int[nSoldiers][n][m];
        int queue[] = new int[3 * n * m];
