            int l = curPathI.size();
            pathI[i] = new int[l];
            pathJ[i] = new int[l];
            for (int k = 0; k < l; k++) {
                pathI[i][k] = curPathI.get(l - k - 1);
                pathJ[i][k] = curPathJ.get(l - k - 1);
