                events.push(turret);
                killed[turret] = true;
                HK.matchingR[HK.matchingL[soldier]] = -1;
                HK.matchingL[soldier] = -1;
                return res == soldier ? -1 : res;
            }
            --pos;
            continue;
        }
    }

