    public static int get(int i, int j, int k) {
        int c = 121 * i + 11 * j + k;

        if (!map.containsKey(c)) return 0;

        return map.get(c);
    }

    public static void add(int i, int j, int k) {
        int count = get(i, j, k);
        int c = 121 * i + 11 * j + k;

        map.put(c, count + 1);

    }

