                for (int jj = 1; jj <= J; jj++) {
                    int j = (jj + i) % J + 1;
                    int c = get(i, j, 0);
                    if (c >= M) {
                        continue;
                    }

                    for (int kk = 1; kk <= K; kk++) {
                        int k = (kk + i + j) % K + 1;
                        int ij = get(i, j, 0);
                        if (ij >= M)continue;
                        int ik = get(i, 0, k);
                        if (ik >= M)continue;
                        int jk = get(0, j, k);
                        if (jk >= M)continue;

                        count ++;
                        add(i, j, k);
                        add(i, j, 0);
                        add(i, 0, k);
                        add(0, j, k);
                    }
                }
            }

