                     isnegative ^=true;
                     result = '1';                   
                 }
                 if(newletter =='k')
                 {

                     result = 'i';                   
                 }               
             }
             if(curletter =='k')
             {
                 if(newletter =='i')
                 {

                     result = 'j';                   
                 }
                 if(newletter =='j')
                 {
                     isnegative ^=true;
                     result = 'i';                   
                 }
                 if(newletter =='k')
                 {
                     isnegative ^=true;
                     result = '1';                   
                 }               
             }
             if(curletter=='1')
             {
                 if(newletter =='i')
                 {
                     result = 'i';
                 }
                 if(newletter =='j')
                 {
                     result = 'j';
                 }
                 if(newletter =='k')
                 {
                     result = 'k';
                 }
             }
             curletter = result;
         }
         isnegative = (X%2==0)?false:isnegative;
         if(((X%4==3)||(X%4==2))&&(curletter!='1'))
         {
             isnegative^=true;
         }
         if(X%2==0)
             curletter = '1';

         if(isnegative&&(curletter =='1'))
             System.out.println("Case #"+cas+": YES");
         else
             System.out.println("Case #"+cas+": NO");
        }
    }
