        String[] sp = s.split(" ");
        N = parseInt(sp[0]);
        int R = parseInt(sp[1]);
        int Y = parseInt(sp[3]);
        int B = parseInt(sp[5]);

        int prev = 0;
        StringBuilder sb = new StringBuilder();
        if(R >= Y && R >= B){
            sb.append("R");
            R--;
            prev = 0;
        }
        else if(Y >= R && Y >= B){
            sb.append("Y");
            Y--;
            prev = 1;
        }
        else{
            sb.append("B");
            B--;
            prev = 2;
        }
        while(R > 0 || Y > 0 || B  > 0){
            if(R == 1 && Y == 1 && B == 1){
                if(prev == 0){
                    if(sb.charAt(0) == 'Y'){
                        sb.append("YBR");
                    }
                    else if(sb.charAt(0) == 'B'){
                        sb.append("BYR");
                    }
                    else{
                        sb.append("BRY");
                    }
                }
                else if(prev == 1){
                    if(sb.charAt(0) == 'Y'){
                        sb.append("BYR");
                    }
                    else if(sb.charAt(0) == 'B'){
                        sb.append("RBY");
                    }
                    else{
                        sb.append("RBY");
                    }
                }
                else{
                    if(sb.charAt(0) == 'Y'){
                        sb.append("RYB");
                    }
                    else if(sb.charAt(0) == 'B'){
                        sb.append("RBY");
                    }
                    else{
                        sb.append("RYB");
                    }
                }

                break;
