             return "(" + r + ", " + h + ")";
         }

         public int hashCode() {
             final int M = 31;
             int res = M * M + M * r + h;
             return (int) res;
         }

         public boolean equals(Object obj) {
             if (obj == null || getClass() != obj.getClass())
                 return false;
             Cake other = (Cake) obj;
             return r == other.r && h == other.h;
         }

         public int compareTo(Cake other) {

             if (r != other.r)
                 return r < other.r ? -1 : 1;
             return h < other.h ? -1 : (h == other.h ? 0 : 1);
         }
     }

