            values[i] = lread();
        }
        long NN = 0;
        for (int i = 0; i < M; i++) {
            p.add(new Pair(keys[i], values[i]));
            NN += values[i];
        }
        int N = 0;
        while ((1L << N) < NN)
            N++;
        Collections.sort(p);
        long[] ans = new long[N];
        TreeMap<Long, Long> sequence = new TreeMap<Long, Long>();
        TreeMap<Long, Long> sequence2 = new TreeMap<Long, Long>();
        for (int i = 0; i < p.size(); i++)
            sequence.put(p.get(i).key, p.get(i).value);
        int cur = 0;
        long zeros = 0;
        long zeros0 = p.get(0).value;
        while ((1 << zeros) < zeros0)
            zeros++;
        c1: for (int k = 0; k < N;) {
            cycle: for (; cur < M; cur++) {
                long add = p.get(cur).key;
                if (add == 0) {
                    while (zeros > 0) {
                        ans[k++] = 0;
                        zeros--;
                    }
                    continue;
                }
                sequence2.clear();
                if (add < 0) {
                    boolean first = true;
                    for (Long x : sequence.keySet()) {
                        if (first && x >= 0) {
                            continue cycle;
                        }
                        first = false;
                        long val = sequence.get(x);
                        if (sequence2.containsKey(x))
                            val -= sequence2.get(x);
                        if (val > 0) {
                            if (!sequence.containsKey(x - add)) {
                                continue cycle;
                            }
                            sequence2.put(x - add, val);
                        } else if (val < 0)
                            continue cycle;
                    }
                } else if (add > 0) {
                    for (Long x : sequence.keySet()) {
                        long val = sequence.get(x);
                        if (sequence2.containsKey(x - add))
                            val -= sequence2.get(x - add);
                        if (val > 0) {
                            if (!sequence.containsKey(x + add)) {
                                continue cycle;
                            }
                            sequence2.put(x, val);
                        } else if (val < 0)
                            continue cycle;
                    }
                }
                TreeMap seq = sequence2;
                sequence2 = sequence;
                sequence = seq;
                ans[k++] = add;
                continue c1;
            }
        }
