    final String problem = "B";





    final String filename = problem + "-small-attempt7";



    public void solve(int test) throws Exception {
        int N = iread(), K = iread();
        int[] S = new int[N - K + 1];
        for (int i = 0; i < S.length; i++) {
            S[i] = iread();
        }

        int[] len = new int[K];

        int sum = -S[0] % K;
        if (sum < 0)
            sum += K;
        for (int i = 0; i < K; i++) {
            int min = 0, max = 0;
            int j = i;
            int val = 0;
            for (; j + K < N; j += K) {
                val += (S[j + 1] - S[j]);
                min = Math.min(min, val);
                max = Math.max(max, val);
            }
            len[i] = max - min;
            sum += min;
            sum %= K;
            if (sum < 0)
                sum += K;
        }
        int ll = 0, s = 0;
        for (int i = 0; i < K; i++) {
            ll = Math.max(ll, len[i]);
        }
        for (int i = 0; i < K; i++) {
            s += ll - len[i];
        }
        int ans = ll;
        if (s < sum) {
            ans++;
            if (s!=0&&test>=10) {
                System.out.println("test");

            }
            System.out.println("increase answer in test #"+test+" s="+s+" sum="+sum);
        } else {
            if( sum!=0)
                System.out.println("not increase answer in test #"+test+" s="+s+" sum="+sum);
        }
        out.write(ans + "");
    }

