         Locale.setDefault(Locale.US);
         InputStream inputStream;
         try {
             final String regex = "D-(small|large).*[.]in";
             File directory = new File(".");
             File[] candidates = directory.listFiles(new FilenameFilter() {
                 public boolean accept(File dir, String name) {
                     return name.matches(regex);
                 }
             });
             File toRun = null;
             for (File candidate : candidates) {
                 if (toRun == null || candidate.lastModified() > toRun.lastModified()) {
                     toRun = candidate;
                 }
             }
             inputStream = new FileInputStream(toRun);
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         OutputStream outputStream;
         try {
             outputStream = new FileOutputStream("d.out");
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         InputReader in = new InputReader(inputStream);
         OutputWriter out = new OutputWriter(outputStream);
         TaskD solver = new TaskD();
         solver.solve(1, in, out);
         out.close();
     }

     static class TaskD {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int r;
                 int c;
                 int d;
                 char[][] map;


                 public void read(InputReader in) {
                     r = in.readInt();
                     c = in.readInt();
                     d = in.readInt();
                     map = IOUtils.readTable(in, r, c);
                 }

                 boolean answer;
                 int sRow;
                 int sCol;
                 int fRow;
                 int fCol;
                 int[][] dst;
                 int[] qRow;
                 int[] qCol;
                 boolean[][] processed;
                 char[][] orig;
                 int cDist;

                 int findDistance() {
                     ArrayUtils.fill(dst, -1);
                     qRow[0] = sRow;
                     qCol[0] = sCol;
                     int size = 1;
                     dst[sRow][sCol] = 0;
                     for (int i = 0; i < size; i++) {
                         int row = qRow[i];
                         int col = qCol[i];
                         for (int j = 0; j < 4; j++) {
                             int nRow = row + MiscUtils.DX4[j];
                             int nCol = col + MiscUtils.DY4[j];
                             if (MiscUtils.isValidCell(nRow, nCol, r, c) && map[nRow][nCol] == '.' &&
                                     dst[nRow][nCol] == -1) {
                                 dst[nRow][nCol] = dst[row][col] + 1;
                                 qRow[size] = nRow;
                                 qCol[size++] = nCol;
                             }
                         }
                     }
                     return dst[fRow][fCol];
                 }

                 void tryAdd(int row, int col) {
                     map[row][col] = '#';
                     processed[row][col] = true;
                     cDist = findDistance();
                     if (cDist == d) {
                         return;
                     }
                     for (int i = 0; i < 4; i++) {
                         int nRow = row + MiscUtils.DX4[i];
                         int nCol = col + MiscUtils.DY4[i];
                         if (!processed[nRow][nCol] && orig[nRow][nCol] == '#') {
                             tryAdd(nRow, nCol);
                             if (cDist == d) {
                                 return;
                             }
                         }
                     }
                 }


                 public void solve() {
                     orig = new char[r][c];
                     for (int i = 0; i < r; i++) {
                         for (int j = 0; j < c; j++) {
                             orig[i][j] = map[i][j];
                         }
                     }
                     sRow = -1;
                     sCol = -1;
                     fRow = -1;
                     fCol = -1;
                     for (int i = 0; i < r; i++) {
                         for (int j = 0; j < c; j++) {
                             if (map[i][j] == 'S') {
                                 map[i][j] = '.';
                                 sRow = i;
                                 sCol = j;
                             }
                             if (map[i][j] == 'F') {
                                 map[i][j] = '.';
                                 fRow = i;
                                 fCol = j;
                             }
                         }
                     }
                     dst = new int[r][c];
                     qRow = new int[r * c];
                     qCol = new int[r * c];
                     int o = findDistance();
                     if (d > o || (o - d) % 2 != 0) {
                         return;
                     }
                     for (int i = 1; i < r - 1; i++) {
                         for (int j = 1; j < c - 1; j++) {
                             map[i][j] = '.';
                         }
                     }
                     cDist = findDistance();
                     if (cDist > d) {
                         return;
                     }
                     processed = new boolean[r][c];
                     for (int i = 0; i < r; i++) {
                         processed[i][0] = processed[i][c - 1] = true;
                     }
                     for (int i = 0; i < c; i++) {
                         processed[0][i] = processed[r - 1][i] = true;
                     }
                     for (int i = 1; i < r - 1 && cDist != d; i++) {
                         if (!processed[i][1] && orig[i][1] == '#') {
                             tryAdd(i, 1);
                         }
                         if (cDist != d && !processed[i][c - 2] && orig[i][c - 2] == '#') {
                             tryAdd(i, c - 2);
                         }
                     }
                     for (int i = 1; i < c - 1 && cDist != d; i++) {
                         if (!processed[1][i] && orig[1][i] == '#') {
                             tryAdd(1, i);
                         }
                         if (cDist != d && !processed[r - 2][i] && orig[r - 2][i] == '#') {
                             tryAdd(r - 2, i);
                         }
                     }
                     for (int i = 2; cDist != d && i < r - 2; i++) {
                         for (int j = 2; cDist != d && j < c - 2; j++) {
                             if (!processed[i][j] && orig[i][j] == '#') {
                                 tryAdd(i, j);
                             }
                         }
                     }
                     answer = true;
                     map[sRow][sCol] = 'S';
                     map[fRow][fCol] = 'F';
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.printLine("Case #" + testNumber + ":", answer ? "POSSIBLE" : "IMPOSSIBLE");
                     if (answer) {
                         for (char[] row : map) {
                             out.printLine(row);
                         }
                     }
                 }
             }, 4);
         }

     }

