public class B {
    int n, k;
    int[] s;

    String solve() {
        int sum = s[0];
        int[] diff = new int[k];
        for (int i = 0; i < k; i++) {
            int shift = 0;
            int minShift = 0;
            int maxShift = 0;
            for (int j = i + k; j < n; j += k) {
                shift += (s[j - k + 1] - s[j - k]);
                minShift = Math.min(minShift, shift);
                maxShift = Math.max(maxShift, shift);
            }
            diff[i] = maxShift - minShift;
            sum += minShift;
        }
        sum %= k;
        sum += k;
        sum %= k;
        Arrays.sort(diff);

        int space = 0;
        int ans = diff[k - 1];
        for (int i = 0; i < k; i++) {
            space += ans - diff[i];
        }
        if (sum > space) {
            ans++;
        }
        return "" + ans;
    }

    public B(Scanner in) {
        n = in.nextInt();
        k = in.nextInt();
        s = new int[n - k + 1];
        for (int i = 0; i < s.length; i++) {
            s[i] = in.nextInt();
        }
    }

    public static void main(String[] args) throws Exception {
